then the unitary matrix lift $F_f$ in ~Eq.~\eqref{eq:Flift-def} is an $(\frac{q}{q-1}\varepsilon, \frac{\mathbb{I}}{q-1})$ approximate representation of $(G, \star)$.

\begin{equation}\label{eq:rep-eq-blr}
\Pr_{g, h \in G}\!\bigl[F_f(g \star h) = F_f(g)F_f(h)\bigr]
= \Pr_{c,d,x,y}\!\bigl[c f(x) + d f(y) = f(cx + dy)\bigr].
\end{equation}

\begin{align*}
F_f\bigl((x,a)\star(y,b)\bigr) &= \sum_{c\in A}\omega^{{\rm Tr}\, cab\,f(b^{-1}x + a^{-1}y)} \ket{c}\bra{c}, \\
F_f(x, a)\,F_f(y, b) &= \sum_{c\in A} \omega^{{\rm Tr}\, c(af(x) + bf(y))} \ket{c}\bra{c}.
\end{align*}

\begin{equation}
\mathbb{E}_{g, h \in G} \Re \left\langle F_f(g)^{*} F_f(h), F_f\left(g^{-1} h\right)\right\rangle_{\sigma} = \mathbb{E}_{g, h \in G} \Re\left\langle F_f(g) F_f(h), F_f\left(g h\right)\right\rangle_{\sigma},
\end{equation}

\begin{align}
