    \mathcal{C}(f) := \mathbb{E}_{g,h} \Re \inner{F_f(g) F_f(h)}{F_f(gh)}_\sigma \ge 1 - \epsilon. \label{eq:gh-pair-correlation}
\end{equation}


To connect the operator pair-correlation directly to the cubic trace of the Fourier coefficients, we express the lift matrices using the inverse Fourier transform, $F_f(x) = \sum_{\chi \in \widehat{G}} \hat{F}_f(\chi) \chi(x)$. Substituting this into the inner product definition of the pair-correlation and using the character homomorphism $\chi(gh) = \chi(g)\chi(h)$, we expand the trace:
\begin{align}
    \mathcal{C}(f) &= \mathbb{E}_{g,h \in G} \Re {\rm Tr}\left( F_f(g)^* F_f(h)^* F_f(gh) \sigma \right) \nonumber \\
    &= \Re {\rm Tr} \left( \sum_{\chi_1, \chi_2, \chi_3} \hat{F}_f^*(\chi_1) \hat{F}_f^*(\chi_2) \hat{F}_f(\chi_3) \sigma \cdot \mathbb{E}_g\left[\overline{\chi_1(g)}\chi_3(g)\right] \mathbb{E}_h\left[\overline{\chi_2(h)}\chi_3(h)\right] \right).
\end{align}
By the orthogonality of characters, the expectations over $g$ and $h$ independently vanish unless $\chi_1 = \chi_3$ and $\chi_2 = \chi_3$. This completely collapses the triple sum to a single sum over $\chi$. Because the Fourier coefficients of the diagonal lift $F_f$ are themselves diagonal matrices (and thus commute), we can rearrange the surviving terms to recover the exact cubic trace expression:
\begin{equation}
    \mathcal{C}(f) = \Re \sum_{\chi \in \widehat{G}} {\rm Tr}\left( \hat{F}_f^*(\chi) \hat{F}_f(\chi) \hat{F}_f^*(\chi) \sigma \right).
\end{equation}

    Because the Fourier coefficients are all fully diagonal since $F_f$ is diagonal, we expand the product
    \[
    \sum_{\chi_{\alpha, k} \in \widehat{G}} {\rm Tr}(\hat{F}_f^*(\chi)\hat{F}_f(\chi)\hat{F}_f^*(\chi) \sigma) = \frac{1}{q-1}\sum_{\alpha \in \mathbb{F}_q^n} \sum_{k=0}^{q-2} \sum_{c \in \mathbb{F}_q^\times} \left| [\hat{F}_f(\chi_{\alpha, k})]_{cc} \right|^2 \overline{[\hat{F}_f(\chi_{\alpha, k})]_{cc}}.
    \]

    Using the substitution $\alpha = c\beta$, summing over all $\alpha$ is equivalent to summing over all $\beta$. 
Substituting our factored coefficient from ~\eqref{eq:factored-coeff} in Proposition~\ref{prop:Ff_fourier}: 
    \begin{align*}
        \sum_{\chi \in \widehat{G}} {\rm Tr}(\hat{F}_f^*(\chi)\hat{F}_f(\chi)\hat{F}_f^*(\chi) \sigma) &= \frac{1}{q-1}\sum_{c \in \mathbb{F}_q^\times} \sum_{\beta \in \mathbb{F}_q^n} \sum_{k=0}^{q-2} |\psi_k(c)\nu_k(\beta)|^2 \overline{\psi_k(c)\nu_k(\beta)} \\
        &= \frac{1}{q-1}\sum_{\beta, k} |\nu_k(\beta)|^2 \overline{\nu_k(\beta)} \sum_{c \in \mathbb{F}_q^\times} \overline{\psi_k(c)},
    \end{align*}
    where 
    \[
    \nu_k(\beta) := \mathbb{E}_{x,b} \left[ \omega^{b(f(x) - \langle \beta, x \rangle)} \overline{\psi_k(b)} \right],
    \]
    is defined in Eq.~\eqref{def:nu-k}.

    Use the indicator function of $\mathbb{F}_q^\times$:
    \[
        \sum_{c \in \mathbb{F}_q^\times} \overline{\psi_k(c)} = (q-1) \mathbb{I}(k=0)
    \] 
we have
    \begin{equation}\label{eq:triple-F-nu0}
        \sum_{\chi \in \widehat{G}} {\rm Tr}(\hat{F}_f^*(\chi)\hat{F}_f(\chi)\hat{F}_f^*(\chi) \sigma) = \sum_{\beta \in \mathbb{F}_q^n} |\nu_0(\beta)|^2 \overline{\nu_0(\beta)}.
    \end{equation}
    Note that $\nu_0(\beta) \in \mathbb{R}$ is related to the hamming distance $\delta(f, \ell_\beta)$ for liner function $\ell_\beta = \inner{f}{\ell_\beta}$ via
    \begin{equation}\label{eq:nu0-hamming}
    \nu_0(\beta) = (1 - \delta(f, \ell_\beta)) - \frac{1}{q-1}\delta(f, \ell_\beta) = 1 - \frac{q}{q-1}\delta(f, \ell_\beta).
    \end{equation}
    Moreover, because the Fourier coefficients sum to identity by unitarity of $F_f$, we have
    \begin{align}
        1& = \frac{1}{q-1}\sum_{\chi\in\hat{G}}{\rm Tr}\left[\hat{F}^*_f(\chi)\hat{F}_f(\chi)\right] , \nonumber \\
        &= \frac{1}{q-1}\sum_{c \in \mathbb{F}_q^\times} \sum_{\beta \in \mathbb{F}_q^n} \sum_k |\psi_k(c)\nu_k(\beta)|^2, \nonumber \\
        &= \sum_{\beta \in \mathbb{F}_q^n} \sum_k |\nu_k(\beta)|^2.
    \end{align}

    Therefore $|\nu_k(\beta)|^2$ is a probability distribution indexed by $(k, \beta)$. Because the $k=0$ probability is a subset, we have
    \begin{equation}
    \sum_{\beta \in \mathbb{F}_q^n} |\nu_0(\beta)|^2 \leq \sum_{\beta \in \mathbb{F}_q^n} \sum_k |\nu_k(\beta)|^2 = 1.
    \end{equation}

    Let $\beta^*$ be the closest linear function such that
    \begin{equation}
    \nu_0(\beta^*) := \max_{\beta \in \mathbb{F}_q^n} \nu_0(\beta).
    \end{equation}
    Therefore from Gowers-Hatami implication in Eq.~\eqref{eq:gh-pair-correlation} and the simplification of Fourier coefficeints in Eq.~\eqref{eq:triple-F-nu0}, we have the bound
    \begin{align}
        1 - \epsilon \leq \Re \sum_{\chi\in\widehat G} {\rm Tr}(\hat{F}_f^*(\chi)\hat{F}_f(\chi)\hat{F}_f^*(\chi) \sigma) = \sum_{\beta \in \mathbb{F}_q^n} |\nu_0(\beta)|^2 \overline{\nu_0(\beta)} \leq  \nu_0(\beta^*) \sum_{\beta \in \mathbb{F}_q^n} |\nu_0(\beta)|^2 \leq  \nu_0(\beta^*).
    \end{align}

    Unpack the relation to the hamming distance, we have
    \begin{equation}
    1 - \frac{q}{q-1} \delta(f, \ell_{\beta^*}) \ge 1 - \epsilon \implies \delta(f, \ell_{\beta^*}) \le \frac{q-1}{q}\epsilon.
    \end{equation}

\begin{align}
    \mathcal{C}(f) &= \mathbb{E}_{g,h \in G} \Re {\rm Tr}\left( F_f(g)^* F_f(h)^* F_f(gh) \sigma \right) \nonumber \\
    &= \Re {\rm Tr} \left( \sum_{\chi_1, \chi_2, \chi_3} \hat{F}_f^*(\chi_1) \hat{F}_f^*(\chi_2) \hat{F}_f(\chi_3) \sigma \cdot \mathbb{E}_g\left[\overline{\chi_1(g)}\chi_3(g)\right] \mathbb{E}_h\left[\overline{\chi_2(h)}\chi_3(h)\right] \right).
\end{align}

\label{randOracleSpec}



For this section, the \emph{randomness oracle specification} will be of a monadic function that takes
nothing and returns an element from a field \(\mathbb{F}\).

\label{uniformSample}



The \emph{uniform sampling query implementation} for a field \(\mathbb{F}\) is a (mathematical) 
query implementation for the randomness oracle specification that samples uniformly from \(\mathbb{F}\).

\label{LPCPVerifier}



A \emph{LPCP verifier} is a verifier with query access to a linear function
$\langle \pi,\cdot \rangle : \Sigma^{\ell(|x|)} \to \Sigma$.

\label{BLR.basicVerifier}


Let \(V_{\mathrm{BLR}(\mathbb{F}_{2}, n)}^{f}\) be the verifier with oracle access to \(f: \mathbb{F}_{2}^n \to \mathbb{F}_{2}\) defined as follows:
\begin{enumerate}
  \item Sample \(x, y \leftarrow \mathbb{F}_2^n\).
  \item Accept if and only if \(f(x) + f(y) = f(x+y)\).
\end{enumerate}

\label{BLR_basic_completeness_ZMod2}




Let \(n > 0\). For every linear function \(f: \mathbb{F}_{2}^n \to \mathbb{F}_{2}\), we have
\[\Pr \left[V_{\mathrm{BLR}(\mathbb{F}_{2}, n)}^{f} = 1\right] = 1.\]

\label{LINEQ}
For a field \(\mathbb{F}\) and parameters \(m, n \in \mathbb{N}\), we define the language
\[\mathrm{LINEQ}(\mathbb{F},m,n) := \{ (M, c) \in \mathbb{F}^{m\times n} \times \mathbb{F}^{m} \mid \exists b\in \mathbb{F}^n, \, Mb = c \}.\]

\label{LINEQ.verifier}
Let \(V_{\mathrm{LINEQ}(\mathbb{F},m,n)}^{\langle b, \cdot \rangle } (M,c)\) be the LPCP verifier defined as follows:
\begin{enumerate}
  \item Sample \(r \leftarrow \mathbb{F}^m\).
  \item Query \(b\in \mathbb{F}^n \) at \(u:= \Transpose{M}r \in \mathbb{F}^n\).
  \item Accept if and only if \(\langle b,u\rangle = \langle c, r\rangle\).
\end{enumerate}

\begin{gather*}
  \Pr_{r\leftarrow \mathbb{F}^m} \left[\langle b, u \rangle =  \langle c , r\rangle \right] = \Pr_{r\leftarrow \mathbb{F}^m} \left[\langle Mb, r \rangle =  \langle c , r\rangle \right] 
  \\= \Pr_{r\leftarrow \mathbb{F}^m} \left[ \sum_{i=1}^{m} (Mb - c)_{i} \cdot r_{i} =  0\right] \leq 1 / |\mathbb{F}|,
\end{gather*}

